from PIL import Image, ImageDraw
from pathlib import Path
import random, math
out=Path('projects/active/repetition-without-a-route')
W,H=900,650
P=(232,225,205); I=(31,34,30); O=(154,72,49)
def base(seed):
 im=Image.new('RGB',(W,H),P); d=ImageDraw.Draw(im); r=random.Random(seed)
 for _ in range(26000):
  x=r.randrange(W);y=r.randrange(H); c=im.getpixel((x,y));v=r.choice([-5,-3,3,5]);im.putpixel((x,y),tuple(max(0,min(255,z+v)) for z in c))
 return im,ImageDraw.Draw(im)
def blob(d,x,y,rx,ry,col): d.ellipse((x-rx,y-ry,x+rx,y+ry),fill=col)
# 1 accumulated deposits: time thickens a few localized knots without a connective route.
im,d=base(521);r=random.Random(521)
for cx,cy,n,spread in [(208,205,115,60),(525,315,180,75),(335,497,90,48),(741,195,70,44)]:
 for i in range(n):
  x=r.gauss(cx,spread);y=r.gauss(cy,spread*.62);rx=r.randint(2,9);ry=r.randint(2,6)
  blob(d,x,y,rx,ry,r.choice([I,I,I,O]))
im.save(out/'052-time-deposits.png')
# 2 successive rings of incomplete impressions: accumulation as bands, broken deliberately, no single crossing.
im,d=base(522)
for cx,cy,rx,ry,start,end,n in [(256,280,150,112,.4,2.55,76),(256,280,112,78,3.35,5.35,55),(637,390,122,90,1.0,3.55,63)]:
 r=random.Random(int(cx+cy+rx));
 for i in range(n):
  a=r.uniform(start,end); x=cx+math.cos(a)*rx+r.gauss(0,9);y=cy+math.sin(a)*ry+r.gauss(0,8);L=r.randint(10,37);T=r.randint(4,11);ang=a+math.pi/2+r.uniform(-.55,.55);dx=math.cos(ang)*L/2;dy=math.sin(ang)*L/2
  d.line((x-dx,y-dy,x+dx,y+dy),fill=r.choice([I,I,O]),width=T)
im.save(out/'052-time-arcs.png')
# 3 pause marks: discrete bunches separated by conspicuous blank intervals, varied scale.
im,d=base(523);r=random.Random(523)
for cx,cy,k in [(182,220,0),(489,165,1),(689,390,2),(316,490,3)]:
 for j in range(18+k*5):
  x=r.gauss(cx,44+k*6); y=r.gauss(cy,34+k*4); L=r.randint(9,70); T=r.randint(3,13); a=r.uniform(-math.pi,math.pi);dx=math.cos(a)*L/2;dy=math.sin(a)*L/2
  d.line((x-dx,y-dy,x+dx,y+dy),fill=r.choice([I,I,I,O]),width=T)
im.save(out/'052-time-pauses.png')
# 4 spreading noise, the warning version: fine deposits expand outward from a dense patch.
im,d=base(524);r=random.Random(524)
for cx,cy,rad,n in [(385,321,65,190),(385,321,145,240),(385,321,260,300)]:
 for _ in range(n):
  a=r.uniform(0,2*math.pi);rr=r.uniform(rad*.72,rad);x=cx+math.cos(a)*rr;y=cy+math.sin(a)*rr*.66
  if 6<x<W-6 and 6<y<H-6:
   sz=r.choice([1,2,3,5]);blob(d,x,y,sz,sz,r.choice([I,I,O]))
im.save(out/'052-time-spread.png')
print('saved four distinct temporal screen studies')
